     1	// Merges the generated overrides (orca-mac-keybindings.js) into
     2	// ~/.orca/keybindings.json's platforms.linux. See orca.nix.
     3	//
     4	//   node orca-mac-keybindings-merge.js <app>/out/shared <owned.json>
     5	//
     6	// The file is Orca's read-write state, so this owns only what it wrote: a
     7	// sidecar, keybindings.nix-owned.json, records the values of the last write.
     8	//   - a key written last time and no longer generated is removed;
     9	//   - a key whose value the UI has changed since is left as the UI's;
    10	//   - everything else in the file is untouched.
    11	// Then the merged file gets Orca's own conflict check. Orca drops every
    12	// action in a conflicting set at load, so a generated key that clashes with
    13	// a UI shortcut is withdrawn instead, and named, leaving the UI's choice and
    14	// the generated action's Linux default.
    15	const fs = require('fs');
    16	const os = require('os');
    17	const path = require('path');
    18	
    19	// Activation runs under set -e, so a throw here would abandon the rest of
    20	// the switch over a keybinding file. Any failure is one line and exit 0;
    21	// the file is then exactly as it was, since writes only ever rename over it.
    22	process.on('uncaughtException', (e) => {
    23	  console.error(`orca: keybinding merge skipped: ${e.message}`);
    24	  process.exit(0);
    25	});
    26	
    27	const [shared, ownedFile] = process.argv.slice(2);
    28	const kb = require(path.resolve(shared, 'keybindings.js'));
    29	const owned = JSON.parse(fs.readFileSync(ownedFile, 'utf8'));
    30	
    31	const dir = path.join(os.homedir(), '.orca');
    32	const dest = path.join(dir, 'keybindings.json');
    33	const sidecar = path.join(dir, 'keybindings.nix-owned.json');
    34	const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
    35	const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
    36	
    37	// Orca's own writer (G$): whole file to a temp name, rename over, and the
    38	// temp removed if either step fails.
    39	function writeJson(file, value) {
    40	  const tmp = `${file}.nix-${process.pid}-${Date.now()}`;
    41	  try {
    42	    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, { flag: 'wx' });
    43	    fs.renameSync(tmp, file);
    44	  } catch (e) {
    45	    fs.rmSync(tmp, { force: true });
    46	    throw e;
    47	  }
    48	}
    49	
    50	fs.mkdirSync(dir, { recursive: true });
    51	let doc;
    52	if (!fs.existsSync(dest)) {
    53	  doc = { version: 1, keybindings: {}, platforms: { darwin: {}, linux: {}, win32: {} } };
    54	} else {
    55	  let why = null;
    56	  try {
    57	    doc = JSON.parse(fs.readFileSync(dest, 'utf8'));
    58	    if (!isObject(doc)) why = 'not a JSON object';
    59	  } catch (e) {
    60	    why = e.message;
    61	  }
    62	  if (why !== null) {
    63	    // Orca's loader rejects it too and says so; overwriting would lose
    64	    // whatever the user was halfway through editing.
    65	    console.error(`orca: ${dest}: ${why}; leaving it for Orca to report`);
    66	    process.exit(0);
    67	  }
    68	}
    69	
    70	let prev = {};
    71	try {
    72	  const s = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
    73	  if (!isObject(s?.linux)) throw new Error('no .linux object');
    74	  prev = s.linux;
    75	} catch (e) {
    76	  // No sidecar is a first run. A bad one stops the merge: it decides what
    77	  // may be overwritten, and reading it as empty overwrites every key the UI
    78	  // has changed.
    79	  if (e.code !== 'ENOENT') {
    80	    console.error(`orca: ${sidecar}: ${e.message}; not merging -- delete it to start over`);
    81	    process.exit(0);
    82	  }
    83	}
    84	
    85	const platforms = isObject(doc.platforms) ? doc.platforms : {};
    86	const linux = isObject(platforms.linux) ? { ...platforms.linux } : {};
    87	// Changed since the last write: the UI's now. Absent (reset in the UI)
    88	// is not a change -- the reset target is this table, so it comes back.
    89	const theirs = new Set(Object.keys(prev).filter((id) => id in linux && !same(linux[id], prev[id])));
    90	for (const id of Object.keys(prev)) {
    91	  if (!theirs.has(id)) delete linux[id];
    92	}
    93	// What the UI had on each key about to be overwritten, for a withdrawal
    94	// below to put back. Stale keys are gone by now, so anything left is the UI's.
    95	const before = {};
    96	const written = {};
    97	for (const [id, bindings] of Object.entries(owned)) {
    98	  if (theirs.has(id)) continue;
    99	  if (id in linux) before[id] = linux[id];
   100	  linux[id] = bindings;
   101	  written[id] = bindings;
   102	}
   103	
   104	// What Orca's loader feeds its conflict pass: common, then the platform
   105	// section over it, with its string shorthand and null/false expanded.
   106	// Common is the root's action keys in the legacy shape with no .keybindings.
   107	const common = doc.keybindings === undefined ? doc : isObject(doc.keybindings) ? doc.keybindings : {};
   108	// Orca's loader (jHn): null/false unbind; a string is a comma list; an array
   109	// of strings may hold comma lists too; one bad chord rejects the whole value,
   110	// leaving the action on its default (undefined here).
   111	const expand = (id, v) => {
   112	  if (v === null || v === false) return [];
   113	  const n =
   114	    typeof v === 'string' ? kb.normalizeKeybindingListForAction(id, v)
   115	      : Array.isArray(v) && v.every((b) => typeof b === 'string') ? kb.normalizeKeybindingArrayForAction(id, v)
   116	        : { ok: false };
   117	  return Array.isArray(n) ? n : n.ok ? [n.value] : undefined;
   118	};
   119	// Each section parsed on its own, then layered (q$): a bad platform value is
   120	// dropped, not allowed to hide a good common one.
   121	const parse = (section) =>
   122	  Object.fromEntries(
   123	    Object.entries(section)
   124	      .filter(([id, v]) => kb.isKeybindingActionId(id) && expand(id, v) !== undefined)
   125	      .map(([id, v]) => [id, expand(id, v)]),
   126	  );
   127	const commonParsed = parse(common);
   128	const effective = { ...commonParsed, ...parse(linux) };
   129	for (;;) {
   130	  const withdrawn = kb
   131	    .findKeybindingConflicts('linux', effective)
   132	    .flatMap((c) => c.actionIds)
   133	    .filter((id) => id in written);
   134	  // Only generated keys are ever withdrawn. A conflict with none left in it
   135	  // -- between UI shortcuts, or a UI shortcut and the Linux default a
   136	  // withdrawal brought back -- is Orca's to report.
   137	  if (withdrawn.length === 0) break;
   138	  for (const id of new Set(withdrawn)) {
   139	    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
   140	    delete written[id];
   141	    if (id in before) {
   142	      linux[id] = before[id];
   143	    } else {
   144	      delete linux[id];
   145	    }
   146	    const restored = id in linux ? expand(id, linux[id]) : undefined;
   147	    if (restored !== undefined) effective[id] = restored;
   148	    else if (id in commonParsed) effective[id] = commonParsed[id];
   149	    else delete effective[id];
   150	  }
   151	}
   152	
   153	doc.version = 1;
   154	doc.platforms = {
   155	  ...platforms,
   156	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
   157	  linux,
   158	  win32: isObject(platforms.win32) ? platforms.win32 : {},
   159	};
   160	writeJson(dest, doc);
   161	// Every key this table claims, written or withdrawn, at its generated value;
   162	// the UI's keep the value last written. Either way a later UI value reads as
   163	// changed, the UI's, rather than as never owned and free to overwrite.
   164	writeJson(sidecar, {
   165	  linux: { ...owned, ...Object.fromEntries([...theirs].map((id) => [id, prev[id]])), ...written },
   166	});
   167	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
   168	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
   169	// Super on Linux. See orca.nix.
   170	//
   171	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
   172	//
   173	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
   174	// facade its comment promises) for the definitions, normalisation and the
   175	// conflict check, so a version bump regenerates the table instead of
   176	// silently drifting from it.
   177	const fs = require('fs');
   178	const path = require('path');
   179	
   180	const [shared, chordsFile] = process.argv.slice(2);
   181	const kb = require(path.resolve(shared, 'keybindings.js'));
   182	
   183	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
   184	// "Cmd+Shift+W". Mouse, switch and media-key binds cannot be an Orca chord;
   185	// anything else that does not translate is an error, not a free chord.
   186	const MODS = { SUPER: 'Cmd', CTRL: 'Ctrl', CONTROL: 'Ctrl', ALT: 'Alt', SHIFT: 'Shift' };
   187	const KEYS = { return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown' };
   188	const taken = new Set();
   189	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
   190	  const parts = chord.split('+').map((s) => s.trim());
   191	  const key = parts.pop();
   192	  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) continue;
   193	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
   194	  const n = mods.every(Boolean) && kb.normalizeKeybinding([...mods, KEYS[key] ?? key].join('+'));
   195	  if (!n || !n.ok) throw new Error(`cannot translate Hyprland bind "${chord}" to an Orca chord`);
   196	  taken.add(n.value);
   197	}
   198	// A digit-index action's one binding stands for its whole 1-9 family.
   199	const isTaken = (id, binding) =>
   200	  kb.isDigitIndexActionId(id)
   201	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
   202	    : taken.has(binding);
   203	
   204	const overrides = {};
   205	// Actions every one of whose Mac chords Hyprland took: left on Linux defaults.
   206	const fellBack = new Set();
   207	for (const def of kb.KEYBINDING_DEFINITIONS) {
   208	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
   209	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
   210	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
   211	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
   212	    return n.value;
   213	  });
   214	  const free = mac.filter((b) => !isTaken(def.id, b));
   215	  if (free.length < mac.length) {
   216	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
   217	  }
   218	  // Every chord taken: leave the action on its Linux default rather than
   219	  // unbinding it. No macOS binding at all is different -- unbound there, so
   220	  // unbound here ([]). Same as the Linux default: nothing to say.
   221	  if (mac.length > 0 && free.length === 0) {
   222	    fellBack.add(def.id);
   223	    continue;
   224	  }
   225	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
   226	  overrides[def.id] = free;
   227	}
   228	
   229	// A fallback can land on a generated chord the Mac table never had to keep
   230	// apart from it. Orca dispatches some actions across scopes, ahead of the
   231	// conflict check's scope groups -- the workspace digits before the tab
   232	// digits -- so with Super+1..9 Hyprland's, workspace.selectByIndex stays on
   233	// Ctrl+1..9 and the Mac tab.selectByIndex (Ctrl+1..9) would never fire.
   234	// Such an action goes back to its own Linux default too, until none is left.
   235	const identities = (id, bindings) =>
   236	  bindings.flatMap((b) => kb.keybindingConflictIdentities(id, b, 'linux'));
   237	for (;;) {
   238	  const held = new Set(
   239	    [...fellBack].flatMap((id) => identities(id, kb.getDefaultBindings(kb.getKeybindingDefinition(id), 'linux'))),
   240	  );
   241	  const shadowed = Object.keys(overrides).filter((id) => identities(id, overrides[id]).some((i) => held.has(i)));
   242	  if (shadowed.length === 0) break;
   243	  for (const id of shadowed) {
   244	    console.error(`${id}: ${overrides[id].join(', ')} is a fallen-back Linux default's`);
   245	    delete overrides[id];
   246	    fellBack.add(id);
   247	  }
   248	}
   249	
   250	// Orca drops every action in a conflicting set at load, with only a line in
   251	// its diagnostics; fail the build instead.
   252	const conflicts = kb.findKeybindingConflicts('linux', overrides);
   253	if (conflicts.length > 0) {
   254	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
   255	}
   256	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
diff --git a/orca.nix b/orca.nix
index 72e5e26b..c51726cb 100644
--- a/orca.nix
+++ b/orca.nix
@@ -89,6 +89,63 @@ let
   # Extracted once, shared by the wrapper's extraInstallCommands below;
   # let bindings are recursive, so position in the block does not matter.
   appimageContents = pkgs.appimageTools.extract { inherit pname version src; };
+
+  # Mac-style shortcuts, the same Super-for-Cmd scheme as gtk's mac-bindings
+  # and ghostty's super+c/v in home.nix: Orca's own macOS defaults, with Cmd
+  # spelled out, which Orca binds to Super (event.metaKey) on Linux. Ctrl+C is
+  # SIGINT again, not copy; Ctrl+Tab and Ctrl+PageUp/Down cycle tabs, as on a
+  # Mac.
+  #
+  # Generated from the app's own keybinding definitions at build time
+  # (nix/orca-mac-keybindings.js), so a version bump picks up new actions.
+  # Chords Hyprland binds are skipped and those actions keep their Linux Ctrl
+  # default -- the compositor would eat them, leaving a dead key. On shiori
+  # that is 19 actions, Super+F (find) and Super+P (go to file) among them,
+  # plus Super+B/N/E, the digits, and their Shift forms; so Ctrl+F/P/B/N/E stay
+  # Orca's. And an action whose Mac chord such a fallback would shadow falls
+  # back too: tab.selectByIndex keeps Alt+1..9, since Ctrl+1..9 stays the
+  # workspaces'. The build log lists every one.
+  #
+  # A running Orca reads the file once; after a switch, restart it (or run its
+  # keybindings reload) for the new table to apply.
+  hyprlandChords = let s = config.wayland.windowManager.hyprland.settings; in
+    lib.concatMap
+      (k: map (b: if builtins.isAttrs b && b ? _args then builtins.head b._args else b) s.${k})
+      # bind, bindl, binde, ...: the lists. `binds` is a config section, a set.
+      (builtins.filter (k: lib.hasPrefix "bind" k && builtins.isList s.${k}) (builtins.attrNames s));
+  macKeybindings = pkgs.runCommand "orca-mac-keybindings" {
+    nativeBuildInputs = [ pkgs.nodejs pkgs.asar pkgs.makeWrapper ];
+  } ''
+    asar extract ${appimageContents}/resources/app.asar app
+    mkdir -p $out/share $out/bin
+    node ${./nix/orca-mac-keybindings.js} app/out/shared \
+      ${pkgs.writeText "hyprland-chords.json" (builtins.toJSON hyprlandChords)} \
+      > $out/share/orca-mac-keybindings.json
+    # The merge runs Orca's conflict check on the merged file at activation,
+    # so the keybinding module (and its one sibling import) ships alongside.
+    mkdir -p $out/lib/shared
+    cp -r app/out/shared/keybindings.js app/out/shared/keybindings \
+      app/out/shared/tui-agent-display-names.js $out/lib/shared/
+    makeWrapper ${pkgs.nodejs}/bin/node $out/bin/orca-mac-keybindings \
+      --add-flags "${./nix/orca-mac-keybindings-merge.js} $out/lib/shared $out/share/orca-mac-keybindings.json"
+    # One real merge, so an Orca bump that moves an import or an export the
+    # merge uses fails here, not as a warning at every activation. The seed
+    # is a string (comma-list) value, so the shorthand parser runs too.
+    mkdir -p $TMPDIR/home/.orca
+    echo '{"version":1,"keybindings":{},"platforms":{"linux":{"zoom.reset":"Alt+0, Alt+Shift+0"}}}' \
+      > $TMPDIR/home/.orca/keybindings.json
+    HOME=$TMPDIR/home $out/bin/orca-mac-keybindings 2> merge.err
+    if [ -s merge.err ] || [ ! -s $TMPDIR/home/.orca/keybindings.json ]; then
+      cat merge.err >&2; exit 1
+    fi
+  '';
+  # ~/.orca/keybindings.json is Orca's read-write state: its settings UI saves
+  # into the same platforms.linux section, by atomic rename, so a home.file
+  # symlink would be replaced on the first edit. So the generated keys are
+  # merged into whatever Orca last wrote, owning only what the last merge
+  # wrote (a sidecar records it), and a UI edit outranks them -- the rules
+  # are at the top of nix/orca-mac-keybindings-merge.js.
+  # tests/orca-mac-keybindings.sh.
 in
 {
   home.packages =
@@ -98,4 +155,9 @@ in
     # same reason parsec gets it.
       (config.lib.nixGL.wrap orca)
     ];
+
+  home.activation.orcaMacKeybindings = lib.mkIf (!isDarwin && isDesktop)
+    (lib.hm.dag.entryAfter [ "writeBoundary" ] ''
+      $DRY_RUN_CMD ${macKeybindings}/bin/orca-mac-keybindings
+    '');
 }

